  function toggleSidebar(){sidebarCollapsed=!sidebarCollapsed;railHint=null;try{if(data.user?.id)localStorage.setItem(sidebarPreferenceKey(data.user.id),sidebarCollapsed?'collapsed':'expanded');}catch{/* The layout remains usable when device storage is disabled. */}}
  function positionRailHint(node:HTMLElement,label:string){const box=node.getBoundingClientRect(),scrollBox=node.closest('.side-nav')?.getBoundingClientRect();if(scrollBox&&(box.bottom<scrollBox.top||box.top>scrollBox.bottom)){railHint=null;return;}railHint={label,left:(node.closest('.sidebar')?.getBoundingClientRect().right??box.right)+10,top:Math.max(24,Math.min(innerHeight-24,box.top+box.height/2))};}
  function showRailHint(event:FocusEvent|PointerEvent,label:string){if(!compactSidebar||('pointerType' in event&&event.pointerType==='touch'))return;const node=event.currentTarget;if(!(node instanceof HTMLElement))return;railHintNode=node;positionRailHint(node,label);}
  function hideRailHint(){railHint=null;railHintNode=null;}
