ung',permission:'dispatch'},{slug:'time',label:'Meine Zeit',permission:'time'},{slug:'leave',label:'Urlaub & Abwesenheit',permission:'time'},{slug:'team',label:'Team',permission:'hr'},{slug:'resources',label:'Fahrzeuge & Geräte',permission:'inventory'}]},{key:'studio',label:'Planungsstudio',icon:'pen',href:'/studio',permissions:['planning'],items:[{slug:'studio',label:'Planungen',permission:'planning'},{slug:'fonts',label:'Schriftenbibliothek',permission:'planning'}]},{key:'manufacturer',label:'Herstellerbibliothek',icon:'box',href:'/manufacturer-assets',permissions:['manufacturer_assets'],items:[]},{key:'reports',label:'Auswertungen',icon:'chart',href:'/reports',permissions:['reports','finance'],items:[{slug:'reports',label:'Übersicht',permission:'reports'},{slug:'cost-estimates',label:'Restschätzungen',permission:'finance'},{slug:'performance-valuations',label:'Leistungsbewertungen',permission:'finance'},{slug:'liquidity-openings',label:'Liquiditätsanfangsbestände',permission:'finance'}]},{key:'documents',label:'Dokumente',icon:'file',href:'/documents',permissions:['documents'],items:[{slug:'documents',label:'Dokumenteneingang',permission:'documents'},{slug:'imports',label:'Datenübernahme',permission:'imports'}]},{key:'administration',label:'Administration',icon:'settings',href:'/settings',permissions:['admin','audit','system'],items:[{slug:'settings',label:'Betrieb & Integration',permission:'admin'},{slug:'rules',label:'Regeln & Freigaben',permission:'admin'},{slug:'audit',label:'Nachweisprotokoll',permission:'audit'},{slug:'jobs',label:'Verarbeitung',permission:'system'}]}];
