  function groupHref(group:{href:string;items:{slug:string;permission:string}[]}){if(['/office','/purchasing'].includes(group.href))return group.href;return group.items.length&&!group.items.some(item=>item.slug===group.href.slice(1)&&canRead(item.permission))?'/'+(group.items.find(item=>canRead(item.permission))?.slug||''):group.href;}
