icon} size={18}/><span class="nav-label">{group.label}</span></a>{/each}<a class="nav-item" class:active={slug==='account'} aria-current={slug==='account'?'page':undefined} href="/account" aria-label="Meine Einstellungen" title="Meine Einstellungen" onpointerenter={event=>showRailHint(event,'Meine Einstellungen')} onpointerleave={hideRailHint} onfocus={event=>showRailHint(event,'Meine Einstellungen')} onblur={hideRailHint}><Icon name="settings" size={18}/><span class="nav-label">Meine Einstellungen</span></a><a class="nav-item" class:active={data.view==='help'} aria-current={data.view==='help'?'page':undefined} href="/help" aria-label="Hilfe & Einführung" title="Hilfe & Einführung" onpointerenter={event=>showRailHint(event,'Hilfe & Einführung')} onpointerleave={hideRailHint} onfocus={event=>showRailHint(event,'Hilfe & Einführung')} onblur={hideRailHint}><Icon name="help" size={18}/><span class="nav-label">Hilfe & Einführung</span></a></nav><div class="side-footer">{#if data.summary?.feedback?.enabled&&data.user}<button class="feedback-fab sidebar-feedback" data-feedback-private aria-label="Feedback" aria-haspopup="dialog" aria-keyshortcuts="Alt+Shift+F" title="Feedback geben · Alt + Umschalt + F" onclick={()=>window.dispatchEvent(new Event('schubert:feedback:open'))} onpointerenter={event=>showRailHint(event,'Feedback geben')} onpointerleave={hideRailHint} onfocus={event=>showRailHint(event,'Feedback geben')} onblur={hideRailHint}><Icon name="pen" size={17}/><span class="nav-label">Feedback</span></button>{/if}<div class="profile"><a class="avatar" href="/account" aria-label="Mein Zugang und persönliche Einstellungen" title="Mein Zugang und persönliche Einstellungen" onpointerenter={event=>showRailHint(event,'Mein Zugang und persönliche Einstellungen')} onpointerleave={hideRailHint} onfocus={event=>showRailHint(event,'Mein Zugang und persönliche Einstellungen')} onblur={hideRailHint}>{initials||'S'}</a><div class="profile-details"><a href="/account" class="profile-n