ne?'Verbunden':'Offline'}</span>{#if permitted(data,'tasks')}<a class="icon-button" class:notification-link={!!data.summary?.unreadNotifications} href="/notifications" aria-label="Mitteilungen öffnen"><Icon name="bell" size={18}/></a>{/if}</div></header><main id="main-content" class="page-content">{#if data.summary?.trainingMode}<div class="training-notice" role="note"><Icon name="help" size={15}/><strong>Testbetrieb</strong><p>Beispieldaten zum Ausprobieren. Keine verbindlichen Belege oder betrieblichen Auswertungen daraus ableiten.</p><a class="text-link" href="/help?from=test">Hinweise zum Testen<Icon name="arrow" size={12}/></a></div>{/if}{#if error}<div class="notice error" role="alert"><Icon name="alert"/><div>{error}</div></div>{/if}{#if data.error}<div class="notice error" role="alert"><Icon name="alert"/><div class="notice-content"><div class="notice-title">Der Arbeitsbereich konnte nicht vollständig geladen werden</div><p>{data.error}</p><button class="btn small mt" onclick={()=>window.location.reload()}>Erneut laden</button></div></div>{/if}{#if activeSubnav.length>1&&!['dashboard','studio','help','detail','workspace'].includes(data.view)}<SectionNavigation items={activeSubnav} active={slug} label={activeGroup.label}/>{/if}{#if data.view==='help'}<Help {data}/>{:else if data.view==='workspace'}<WorkspaceHub {data}/>{:else if data.view==='dashboard'}<Dashboard {data}/>{:else if data.module?.slug==='manufacturer-assets'}{#await import('#lib/components/ManufacturerAssets.svelte') then library}{@const ManufacturerAssets=library.default}<ManufacturerAssets {data}/>{/await}{:else if data.view==='list'&&data.module}{#key data.module.slug}<RecordList {data}/>{/key}{:else if data.view==='detail'&&data.module&&data.detail}{#key data.detail.id}{#if data.module.slug==='customers'}<CustomerWorkspace {data}/>{:else}<RecordDetail {data}/>{/if}{/key}{:else if data.view==='time'}<TimeView {data}/>{:else if data.view==='reports'}<Reports {data}/>{:else if data.view==='settings'}<Settings {data}/>{:else if data.view==='studio'}{#await loadStudio(studioAttempt)}<div class="panel"><div class="empty-state"><Icon name="refresh" class="spin" size={28}/><h3 class="mt">Planungsstudio wird geladen</h3><p>Die Zeichenwerkzeuge werden für diesen Arbeitsbereich vorbereitet.</p></div></div>{:then studio}{@const Studio=studio.default}<Studio {data}/>{:catch}<div class="notice error"><Icon name="alert"/><div><strong>Das Planungsstudio konnte nicht geöffnet werden.</strong><p class="small mt">Prüfen Sie Ihre Verbindung und versuchen Sie es erneut. Gespeicherte Planstände bleiben erhalten.</p><div class="inline-actions mt"><button class="btn primary" onclick={()=>studioAttempt+=1}>Studio erneut öffnen<Icon name="refresh" size={15}/></button><button class="btn" onclick={()=>window.location.reload()}>Seite neu laden</button></div></div></div>{/await}{:else}<section class="panel"><div class="empty-state"><div class="empty-icon"><Icon name="lock"/></div><h3>Dieser Bereich ist nicht verfügbar</h3><p>Prüfen Sie Ihre Berechtigung oder öffnen Sie einen anderen Arbeitsbereich.</p><a class="btn" href="/">Zur Tagesübersicht</a></div></section>{/if}</main></div><nav class="mobile-nav" class:with-feedback={!!data.summary?.feedback?.enabled&&!!data.user} aria-label="Mobile Hauptnavigation"><a href="/" class:active={data.view==='dashboard'}><Icon name="home" size={21}/>Heute</a><a href={mobileTime.href} class:active={slug===mobileTime.href.slice(1)}><Icon name={mobileTime.icon} size={21}/>{mobileTime.label}</a><a href={mobileWork.href} class:active={slug===mobileWork.href.slice(1)}><Icon name={mobileWork.icon} size={21}/>{mobileWork.label}</a><button class:active={menuOpen} aria-expanded={menuOpen} onclick={()=>menuOpen=!menuOpen}><Icon name="menu" size={21}/>Mehr</button>{#if data.summary?.feedback?.enabled&&data.user}<button aria-haspopup="dialog" data-feedback-private onclick={()=>window.dispatchEvent(new Event('schubert:feedback:open'))}><Icon name="pen" size={21}/>Feedback</button>{/if}</nav><Assistant {data}/><FeedbackWidget {data} launcher={false}/>{#if !data.error&&Object.hasOwn(data.summary,'onboarding')&&permitted(data,'account.self')&&!['completed','deferred'].includes(data.summary?.onboarding?.status)}<Onboarding {data}/>{/if}</div>{/if}
{#if logoutPending}<div class="modal-backdrop" role="presentation"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="logout-title" tabindex="-1" use:focusTrap><header class="modal-header"><div><h2 id="logout-title">Zeiten noch nicht übertragen</h2><p>{unsent} Aufzeichnung(en) warten auf Bestätigung.</p></div></header><div class="modal-body"><p>Die lokalen Zeiten bleiben Ihrem persönlichen Zugang zugeordnet und werden beim Abmelden nicht gelöscht. Melden Sie sich zum Übertragen wieder mit demselben Konto an.</p></div><footer class="modal-footer"><button class="btn" onclick={()=>logoutPending=false}>Zurück</button><a class="btn primary" href="/time" onclick={()=>logoutPending=false}>Jetzt synchronisieren</a><button class="btn" onclick={()=>logout(true)} disabled={loggingOut}>Abmelden & lokal behalten</button></footer></div></div>{/if}
